SELECT CASE WHEN suppliers.city IN ('Berlin', 'Bangkok') THEN 'priority' ELSE 'other' END AS city_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(products.category))) AS category_values, SORT_ARRAY(COLLECT_SET(products.brand)) AS brand_list FROM products INNER JOIN suppliers ON products.supplier_id = suppliers.id WHERE suppliers.country = 'SG' GROUP BY CASE WHEN suppliers.city IN ('Berlin', 'Bangkok') THEN 'priority' ELSE 'other' END;
